package org.brightstats.stats;

import java.nio.file.*;
import java.util.*;
import com.google.gson.*;

public final class GroupChecks {
    private static int checks;private static double maximum;
    private static void check(boolean value){checks++;if(!value)throw new AssertionError("Group check "+checks);}
    private static void close(double a,double b,String label){checks++;if(Double.isNaN(a)&&Double.isNaN(b))return;double d=Math.abs(a-b);if(!Double.isFinite(d)||d>2e-10*Math.max(1,Math.abs(b)))throw new AssertionError(label+": "+a+" != "+b);maximum=Math.max(maximum,d);}
    private static void reject(Runnable action){try{action.run();throw new AssertionError("Invalid groups accepted");}catch(IllegalArgumentException expected){checks++;}}
    public static void main(String[] args)throws Exception{
        Gson gson=new GsonBuilder().serializeSpecialFloatingPointValues().setPrettyPrinting().create();var nativeCases=JsonParser.parseString(Files.readString(Path.of(args[0]))).getAsJsonArray();
        for(var item:nativeCases){var value=item.getAsJsonObject();int[] sizes=gson.fromJson(value.get("sizes"),int[].class);double[] estimates=gson.fromJson(value.get("estimates"),double[].class),errors=gson.fromJson(value.get("errors"),double[].class);var actual=GroupInference.evaluate(estimates[0],estimates[1],errors[0],errors[1],sizes[0],sizes[1],true,true);int index=0;for(var test:List.of(actual.parametric(),actual.welch())){double[] expected=gson.fromJson(value.get(index++==0?"parametric":"welch"),double[].class);close(test.statistic(),expected[0],"Original MGA statistic");close(test.degreesOfFreedom(),expected[1],"Original MGA df");close(test.pValue(),expected[2],"Original MGA probability");}}
        Random random=new Random(20261108);for(boolean reference:new boolean[]{false,true})for(int repeat=0;repeat<8;repeat++){double[] a=new double[31],b=new double[37];for(int i=0;i<a.length;i++)a[i]=repeat%2==0?random.nextGaussian():random.nextInt(4);for(int i=0;i<b.length;i++)b[i]=repeat%2==0?random.nextGaussian():random.nextInt(4);double originalA=.2,originalB=-.1,offset=originalA-Arrays.stream(a).average().orElseThrow()-originalB+Arrays.stream(b).average().orElseThrow(),mass=0;for(double x:a)for(double y:b){double d=x-y+offset;if(d>0)mass++;else if(!reference&&d==0)mass+=.5;}close(GroupInference.nonparametric(originalA,originalB,a,b,reference),1-mass/(a.length*b.length),"Brute all-pairs PLS-MGA");}
        close(GroupInference.nonparametric(1,1,new double[]{1,1},new double[]{1,1},false),.5,"Half-weighted ties");close(GroupInference.nonparametric(1,1,new double[]{1,1},new double[]{1,1},true),1,"Reference strict ties");check(Double.isNaN(GroupInference.nonparametric(0,0,new double[]{0,1},new double[]{0,1},true)));
        var zero=PermutationInference.evaluate(0,new double[]{-.5,0,.5},.05,true,false,false);close(zero.pValue(),1,"Standard zero difference");var referenceZero=PermutationInference.evaluate(0,new double[]{-.5,0,.5},.05,true,false,true);close(referenceZero.pValue(),0,"Reference zero difference");check(referenceZero.referenceZeroDifference());
        var raw=org.brightstats.data.DataPreparation.parse("x,y,group,ignored\n1,2,A,demo\n2,NA,B,demo\n3,4,B,demo\n4,5,A,demo\n5,6,B,demo\n6,7,A,demo\n7,8,C,demo\n8,9,B,demo\n",',');var prep=new org.brightstats.data.DataPreparation.Settings(',',org.brightstats.data.DataPreparation.Decimal.DOT,"NA",org.brightstats.data.DataPreparation.Missing.REMOVE_ROWS);var definitions=List.of(new org.brightstats.data.DataPreparation.Column("x",org.brightstats.data.DataPreparation.Kind.NUMERIC),new org.brightstats.data.DataPreparation.Column("y",org.brightstats.data.DataPreparation.Kind.NUMERIC),new org.brightstats.data.DataPreparation.Column("group",org.brightstats.data.DataPreparation.Kind.TEXT),new org.brightstats.data.DataPreparation.Column("ignored",org.brightstats.data.DataPreparation.Kind.IGNORE));var history=org.brightstats.data.ImportHistory.capture("synthetic.csv",raw,prep,definitions);var labels=org.brightstats.data.GroupMembership.columns(history);check(labels.get("group [source column 3]").equals(List.of("A","B","A","B","A","C","B")));check(!labels.containsKey("ignored [source column 4]"));
        JsonArray cases=new JsonArray();for(int variant=0;variant<4;variant++){
            int na=variant==0?31:variant==3?200:80,nb=variant==0?37:variant==3?220:90,p=variant==0?2:6,extra=variant==2?3:0;double[][] data=new double[na+nb+extra][p];
            for(int i=0;i<data.length;i++){boolean a=i<na;double x=random.nextGaussian()+(a?0:.9),y=(variant==0?(a?.8:-.2):.6)*x+.7*random.nextGaussian()+(a?0:.3);if(variant==0){data[i][0]=x;data[i][1]=y;}else for(int j=0;j<6;j++)data[i][j]=2*j+(j<3?x:y)*new double[]{.9,.75,.6}[j%3]+(variant==3?.35:.6)*random.nextGaussian();}
            List<PlsSem.Block> blocks=variant==0?List.of(new PlsSem.Block("A",new int[]{0},PlsSem.Mode.A),new PlsSem.Block("B",new int[]{1},PlsSem.Mode.A)):List.of(new PlsSem.Block("A",new int[]{0,1,2},variant==2?PlsSem.Mode.B:PlsSem.Mode.A),new PlsSem.Block("B",new int[]{3,4,5},PlsSem.Mode.A));var edges=List.of(new PlsSem.Edge(0,1));var model=new PlsSem.Options(5000,1e-11,PlsSem.Weighting.PATH);var selection=new PlsGroups.Selection("Group A","Group B",java.util.stream.IntStream.range(0,na).toArray(),java.util.stream.IntStream.range(na,na+nb).toArray());
            for(var convention:RegressionBootstrap.Convention.values()){
                boolean reference=convention==RegressionBootstrap.Convention.REFERENCE_4_1_2_1,consistent=variant==3;var settings=new PlsPermutation.Options(40,42,.05,convention,!(reference&&variant==0),true,variant>0);var permutation=PlsPermutation.fit(data,blocks,edges,model,selection,consistent,settings,null);check(permutation.successful()>=32&&permutation.successful()+permutation.failed()==40);check(permutation.point().excludedRows()==extra);check(consistent?permutation.micom().isEmpty():permutation.micom().size()==2);
                if(!consistent){for(var test:permutation.micom()){check(test.correlationDraws().length==permutation.successful());check(variant>0?!test.verdict().equals("UNCONFIRMED_CONFIGURAL"):test.verdict().equals("UNCONFIRMED_CONFIGURAL"));}if(variant==1)check(Math.abs(permutation.micom().get(0).meanDifference())>.1);}
                var interval=variant==0&&!reference?BootstrapIntervals.Method.BCA:variant==3?BootstrapIntervals.Method.BCA:BootstrapIntervals.Method.PERCENTILE;var bootstrapOptions=new Bootstrap.Options(40,42,.95,interval,convention,!(reference&&variant==0));var bootstrap=PlsGroupBootstrap.fit(data,blocks,edges,model,selection,consistent,bootstrapOptions,true,null);check(bootstrap.successful()>=32&&bootstrap.successful()+bootstrap.failed()==40);check(bootstrap.comparisons().size()==permutation.tests().size());for(var comparison:bootstrap.comparisons()){check(comparison.groupADraws().length==bootstrap.successful());check(Double.isFinite(comparison.mgaDirectionalP())||reference&&Math.abs(comparison.groupA().original())<=1e-10&&Math.abs(comparison.groupB().original())<=1e-10);}
                JsonObject test=new JsonObject();test.addProperty("variant",variant);test.addProperty("consistent",consistent);test.add("observations",gson.toJsonTree(data));test.add("blocks",gson.toJsonTree(blocks));test.add("edges",gson.toJsonTree(edges));test.add("modelOptions",gson.toJsonTree(model));test.add("selection",gson.toJsonTree(selection));test.add("permutationOptions",gson.toJsonTree(settings));test.add("bootstrapOptions",gson.toJsonTree(bootstrapOptions));test.add("permutation",gson.toJsonTree(permutation));test.add("bootstrap",gson.toJsonTree(bootstrap));cases.add(test);
            }
        }
        reject(()->new PlsGroups.Selection("A","B",new int[]{0,1,2},new int[]{2,3,4}));reject(()->new PlsGroups.Selection("A","A",new int[]{0,1,2},new int[]{3,4,5}));reject(()->new PlsGroups.Selection("A","B",new int[]{0,0,1},new int[]{3,4,5}));reject(()->new PlsPermutation.Options(29,42,.05,RegressionBootstrap.Convention.STANDARD,true,false,false));reject(()->new PlsPermutation.Options(40,42,.05,RegressionBootstrap.Convention.STANDARD,false,false,false));
        Thread.currentThread().interrupt();try{PlsPermutation.shuffle(new Random(42),10,true);throw new AssertionError("Group shuffle ignored cancellation");}catch(java.util.concurrent.CancellationException expected){checks++;}finally{Thread.interrupted();}
        Path output=Path.of(args[1]);Files.createDirectories(output);Files.writeString(output.resolve("cases.json"),gson.toJson(cases));System.out.println("{\"group_cases\":"+cases.size()+",\"original_mga_math_cases\":"+nativeCases.size()+",\"checks\":"+checks+",\"maximum_original_math_difference\":"+maximum+"}");
    }
}
